// CompareFriendship is the generated lifecycle comparison boundary. Pass stored snapshots and the effective assignment draft; its values are not transformed or compared to the result. Both snapshots, when present, must have the same primary key. This function performs no database work or automatic capture.
func CompareFriendship(before, after foundryvalue.Optional[Friendship], assigned FriendshipDraft) (FriendshipChanges, error) {
	before = foundryFriendshipSnapshot(before)
	after = foundryFriendshipSnapshot(after)
	var changes FriendshipChanges
	var err error
	changes.fields.ID, err = lifecycle.CompareModelField(codec.ID[Friendship](), before, after, assigned.fieldID.IsSet(), func(item Friendship) model.ID[Friendship] { return item.ID })
	if err != nil {
		return FriendshipChanges{}, fmt.Errorf("compare Friendship.ID: %w", err)
	}
	if before.IsSet() && after.IsSet() && (changes.fields.ID.Changed() || changes.fields.ID.Assigned()) {
		return FriendshipChanges{}, foundryfault.New(foundryfault.Invalid, "model change cannot replace or assign its existing primary key")
	}
	changes.fields.FromID, err = lifecycle.CompareModelField(codec.ID[Member](), before, after, assigned.fieldFromID.IsSet(), func(item Friendship) model.ID[Member] { return item.FromID })
	if err != nil {
		return FriendshipChanges{}, fmt.Errorf("compare Friendship.FromID: %w", err)
	}
	changes.fields.ToID, err = lifecycle.CompareModelField(codec.ID[Member](), before, after, assigned.fieldToID.IsSet(), func(item Friendship) model.ID[Member] { return item.ToID })
	if err != nil {
		return FriendshipChanges{}, fmt.Errorf("compare Friendship.ToID: %w", err)
	}
	changes.before = before
	changes.after = after
	return changes, nil
}
func foundryFriendshipSnapshot(snapshot foundryvalue.Optional[Friendship]) foundryvalue.Optional[Friendship] {
	item, present := snapshot.Get()
	if !present {
		return foundryvalue.Optional[Friendship]{}
	}
	return foundryvalue.Set(Friendship{
		ID:     item.ID,
		FromID: item.FromID,
		ToID:   item.ToID,
	})
}

